process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const TOK=process.env.GH_TOKEN||''; const REPO=process.env.GH_REPO||'raimis079-creator/petshop-bridge';
const WP=process.env.WP_URL||'https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from(process.env.WP_USER+':'+process.env.WP_APP_PASS).toString('base64');
const B64='';
const VER='psk304-klik-2';
const out={v:VER,zingsniai:[]};
const miegok=ms=>new Promise(r=>setTimeout(r,ms));
async function put(p,buf,m){ const u='https://api.github.com/repos/'+REPO+'/contents/'+p; const h={Authorization:'Bearer '+TOK,'Content-Type':'application/json'};
  let sha=null; try{const g=await fetch(u,{headers:h}); if(g.ok){sha=(await g.json()).sha;}}catch(e){}
  const b={message:m,content:buf.toString('base64')}; if(sha)b.sha=sha;
  return (await fetch(u,{method:'PUT',headers:h,body:JSON.stringify(b)})).status; }
const A={Authorization:AUTH,'Content-Type':'application/json'}; const SNIP=WP+'/wp-json/code-snippets/v1/snippets';
let sid=null,pg=null;
async function Z(pav,fn){ try{ const r=await fn(); out.zingsniai.push({z:pav,ok:true,d:r===undefined?'':String(r).slice(0,120)}); }
  catch(e){ out.zingsniai.push({z:pav,ok:false,d:String(e).slice(0,200)});
    if(pg) try{ await put('analize/fail_'+out.zingsniai.length+'.png',await pg.screenshot({fullPage:true}),VER+' fail'); }catch(e2){}
    throw e; } }
try{
  try{ const l=await fetch(SNIP,{headers:A}); const arr=JSON.parse(await l.text());
  for(const s of (Array.isArray(arr)?arr:[]).filter(s=>s.active&&/^TEMP/.test(s.name||''))){
    await fetch(SNIP+'/'+s.id,{method:'POST',headers:A,body:JSON.stringify({id:s.id,active:false})}); } }catch(e){}
  const c=await fetch(SNIP,{method:'POST',headers:A,body:JSON.stringify({name:'TEMP PS '+VER,
    code:Buffer.from(B64,'base64').toString('utf8'),scope:'global',active:true,priority:5})});
  const ct=await c.text(); out.kurimas=c.status; try{sid=JSON.parse(ct).id;}catch(e){out.kurimo_atsakas=ct.slice(0,300);}
  await miegok(9000);
  async function faze(f){ const r=await fetch(WP+'/?ps_f19='+f+'&r='+Date.now(),{headers:{'User-Agent':'Mozilla/5.0','Cache-Control':'no-cache'}});
    const t=await r.text(); let j; try{ j=JSON.parse(t);}catch(e){ throw new Error(f+' ne JSON: '+t.slice(0,200)); }
    if(j.FATAL) throw new Error(f+' '+j.FATAL); return j; }
  out.DEP3=await faze('DEP3'); await miegok(3000);
  const P=await faze('P4'); out.P4={sid:P.sid,uid:P.uid};
  const {chromium}=await import('playwright');
  const br=await chromium.launch(); const cx=await br.newContext({ignoreHTTPSErrors:true,viewport:{width:1300,height:1000}});
  await cx.addCookies([{name:P.cookie_name,value:P.cookie_val,domain:'dev.avesa.lt',path:'/'}]);
  pg=await cx.newPage();
  const kons=[]; pg.on('pageerror',e=>kons.push(String(e).slice(0,150)));
  await Z('atidarymas',async()=>{ await pg.goto(P.url,{waitUntil:'networkidle',timeout:60000}); await miegok(1200);
    try{ await pg.getByText('PRIIMTI',{exact:true}).first().click({timeout:3000}); await miegok(500);}catch(e){}
    if(!(await pg.locator('.psn3-panele').count())) throw new Error('paneles nera'); });
  await Z('drawer atidarymas (+Prideti preke)',async()=>{
    await pg.locator('button.psn3-nk',{hasText:'Pridėti prekę'}).first().click({timeout:6000}); await miegok(500);
    const ok=await pg.evaluate(()=>{var d=document.getElementById('psn3-drawer');if(!d)return false;var r=d.getBoundingClientRect();return d.className.includes('psn3-rod')&&r.width>50&&r.x<1300&&getComputedStyle(d).visibility==='visible'});
    if(!ok) throw new Error('drawer nematomas'); });
  await Z('Prideti is drawer',async()=>{
    await Promise.all([pg.waitForNavigation({timeout:30000}),pg.locator('button.psn3-prid').first().click()]);
    await miegok(800);
    const n=await pg.locator('.psn3-pr').count();
    if(n<2) throw new Error('prekiu eiluciu '+n); return 'prekiu: '+n; });
  await Z('Keisti prekes (redagavimas)',async()=>{
    await pg.locator('button.psn3-nk',{hasText:'Keisti prekes'}).click({timeout:6000}); await miegok(400);
    const ok=await pg.evaluate(()=>{var r=document.querySelector('.psn3-red');return r&&getComputedStyle(r).display!=='none'});
    if(!ok) throw new Error('stepperiai nepasirode'); });
  await Z('kiekis +1',async()=>{
    await Promise.all([pg.waitForNavigation({timeout:30000}),pg.locator('button.psn3-step',{hasText:'+'}).first().click()]);
    await miegok(600);
    const t=await pg.locator('.psn3-vnt').first().textContent();
    if(!t.includes('2')) throw new Error('kiekis liko '+t); return t.trim(); });
  await Z('Daznumas Keisti',async()=>{
    await pg.locator('button.psn3-keisti').first().click({timeout:6000}); await miegok(400);
    const ok=await pg.evaluate(()=>{var f=document.querySelector('[id^=psn3-daz-]');return f&&f.className.includes('psn3-rod')});
    if(!ok) throw new Error('daznio forma neatsidare'); });
  await Z('Daznumas -> kas 6 sav.',async()=>{
    await pg.locator('[id^=psn3-daz-] select').selectOption('42');
    await Promise.all([pg.waitForNavigation({timeout:30000}),pg.locator('[id^=psn3-daz-] button.psn3-nk',{hasText:'Išsaugoti'}).click()]);
    await miegok(600);
    const t=await pg.content();
    if(!t.includes('Kas 6 savaites')) throw new Error('etikete nepasikeite'); });
  await Z('Pristatymas Keisti + kurjeris',async()=>{
    await pg.locator('button.psn3-keisti').nth(1).click({timeout:6000}); await miegok(400);
    await pg.locator('[id^=psn3-pr-] input[value=kurjeris]').check();
    await Promise.all([pg.waitForNavigation({timeout:30000}),pg.locator('[id^=psn3-pr-] button.psn3-nk',{hasText:'Išsaugoti'}).click()]);
    await miegok(600);
    const t=await pg.content();
    if(!t.includes('Venipak kurjeris')) throw new Error('pristatymas nepasikeite'); });
  await Z('SMS jungiklis',async()=>{
    await Promise.all([pg.waitForNavigation({timeout:30000}),pg.locator('.psn3-jung-l input').check({force:true})]);
    await miegok(600);
    const ok=await pg.locator('.psn3-jung-l input').isChecked();
    if(!ok) throw new Error('SMS neissijunge'); });
  out.pageerrors=kons.slice(0,6);
  await put('analize/klik_final.png',await pg.screenshot({fullPage:true}),VER+' final');
  await br.close();
  out.CL4=await faze('CL4');
  out.VISKAS_ZALIA=out.zingsniai.every(z=>z.ok);
}catch(e){ out.klaida=String(e).slice(0,400); try{ out.CL4=await (async()=>{const r=await fetch(WP+'/?ps_f19=CL4&r='+Date.now(),{headers:{'User-Agent':'Mozilla/5.0'}});return JSON.parse(await r.text());})(); }catch(e2){} }
try{ if(sid) await fetch(SNIP+'/'+sid,{method:'POST',headers:A,body:JSON.stringify({id:sid,active:false})}); }catch(e){}
await put('analize/psk302.json', Buffer.from(JSON.stringify(out,null,1)), VER);
console.log('ok');
